    internal fun resolve(
        event: Match,
        teamName: String,
        shortName: String,
        abbreviation: String,
        teamId: String,
        providerUrl: String?,
    ): String? {
        val aliases = listOf(teamName, shortName, abbreviation).map(::key).filter(String::isNotBlank)
        val direct = when (event.sport) {
            Sport.RUGBY_LEAGUE, Sport.AUSSIE_RULES -> aliases.firstNotNullOfOrNull(rugbyLeague::get)
            Sport.BASKETBALL -> aliases.firstNotNullOfOrNull(nba::get)
            Sport.FOOTBALL -> aliases.firstNotNullOfOrNull(nfl::get)
            Sport.BASEBALL -> aliases.firstNotNullOfOrNull(mlb::get)
            Sport.SOCCER -> aliases.firstNotNullOfOrNull(soccer::get)
            else -> null
        }
        if (direct != null) return direct

        if ((event.sport == Sport.RUGBY || event.sport == Sport.RUGBY_LEAGUE) && teamId.isNotBlank()) {
            return "https://a.espncdn.com/i/teamlogos/rugby/teams/500/" +
                java.net.URLEncoder.encode(teamId, "UTF-8") + ".png"
        }
        if (event.sport == Sport.HOCKEY && abbreviation.isNotBlank()) {
            return "https://a.espncdn.com/i/teamlogos/nhl/500/" + abbreviation.lowercase(Locale.ROOT) + ".png"
        }
        return upgradeProvider(providerUrl)
    }

    internal fun competition(event: Match, providerUrl: String?): String? {
        val label = listOf(event.feed, event.leagueSlug, event.leagueName, event.title)
            .joinToString(" ").lowercase(Locale.ROOT)
        if (event.sport == Sport.RUGBY_LEAGUE && "world cup" in label) {
            return "https://r2.thesportsdb.com/images/media/league/badge/sxoc6h1768739073.png"
        }
        return upgradeProvider(providerUrl)
    }

    private fun upgradeProvider(raw: String?): String? {
        val url = raw?.takeIf { it.startsWith("https://") } ?: return null
        if (url.contains("thesportsdb.com")) {
            return url.removeSuffix("/medium").removeSuffix("/small").removeSuffix("/tiny")
        }
        if (!url.contains("a.espncdn.com")) return url
        return url
            .replace(Regex("/(?:40|50|60|100|200|250|300)/"), "/500/")
            .replace(Regex("/teams/(?:40|50|60|100|200|250|300)/"), "/teams/500/")
    }

    private fun key(value: String): String = Normalizer.normalize(value, Normalizer.Form.NFD)
        .replace(Regex("\\p{M}+"), "")
        .lowercase(Locale.ROOT)
        .replace(Regex("[^a-z0-9]+"), " ")
        .trim()
}